// src/auth/mod.rs
pub mod error;
pub mod models;
pub mod password;
pub mod token;
pub mod repository;
pub mod service;

// Re-export main types
pub use error::{AuthError, AuthResult};
pub use models::{User, Credentials, AuthToken, UserId};
pub use service::AuthenticationService;

// src/auth/models.rs
use std::time::SystemTime;

/// Unique identifier for users
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct UserId(uuid::Uuid);

impl UserId {
    pub fn new() -> Self {
        Self(uuid::Uuid::new_v4())
    }
}

/// User entity with secure password storage
#[derive(Debug, Clone)]
pub struct User {
    pub id: UserId,
    pub email: String,
    pub username: String,
    password_hash: String,  // Private field
    pub created_at: SystemTime,
    pub updated_at: SystemTime,
}

/// Credentials for login
#[derive(Debug, Clone)]
pub struct Credentials {
    pub email: String,
    pub password: String,
}

/// Registration data
#[derive(Debug, Clone)]
pub struct RegistrationData {
    pub email: String,
    pub username: String,
    pub password: String,
}

/// Authentication token for sessions
#[derive(Debug, Clone)]
pub struct AuthToken {
    pub token: String,
    pub user_id: UserId,
    pub expires_at: SystemTime,
}

// src/auth/service.rs
use crate::auth::*;

pub struct AuthenticationService<R, P, T> 
where
    R: UserRepository,
    P: PasswordHasher,
    T: TokenGenerator,
{
    repository: R,
    password_hasher: P,
    token_generator: T,
}

impl<R, P, T> AuthenticationService<R, P, T>
where
    R: UserRepository,
    P: PasswordHasher,
    T: TokenGenerator,
{
    /// Create a new authentication service
    pub fn new(repository: R, password_hasher: P, token_generator: T) -> Self {
        Self {
            repository,
            password_hasher,
            token_generator,
        }
    }

    /// Register a new user
    pub async fn register(&self, data: RegistrationData) -> AuthResult<User> {
        // Validate input
        self.validate_registration(&data)?;

        // Check if user already exists
        if self.repository.find_by_email(&data.email).await?.is_some() {
            return Err(AuthError::UserAlreadyExists);
        }

        // Hash password
        let password_hash = self.password_hasher.hash_password(&data.password)?;

        // Create user
        let user = User {
            id: UserId::new(),
            email: data.email,
            username: data.username,
            password_hash,
            created_at: SystemTime::now(),
            updated_at: SystemTime::now(),
        };

        // Save to repository
        self.repository.save(&user).await?;

        Ok(user)
    }

    /// Authenticate user and generate token
    pub async fn login(&self, credentials: Credentials) -> AuthResult<AuthToken> {
        // Find user by email
        let user = self.repository
            .find_by_email(&credentials.email)
            .await?
            .ok_or(AuthError::InvalidCredentials)?;

        // Verify password
        if !self.password_hasher.verify_password(&credentials.password, &user.password_hash)? {
            return Err(AuthError::InvalidCredentials);
        }

        // Generate token
        let token = self.token_generator.generate_token(user.id)?;

        Ok(token)
    }

    /// Validate an authentication token
    pub async fn validate_token(&self, token: &str) -> AuthResult<User> {
        // Verify and decode token
        let user_id = self.token_generator.validate_token(token)?;

        // Retrieve user
        let user = self.repository
            .find_by_id(user_id)
            .await?
            .ok_or(AuthError::UserNotFound)?;

        Ok(user)
    }

    /// Change user password
    pub async fn change_password(
        &self,
        user_id: UserId,
        old_password: &str,
        new_password: &str,
    ) -> AuthResult<()> {
        // Retrieve user
        let mut user = self.repository
            .find_by_id(user_id)
            .await?
            .ok_or(AuthError::UserNotFound)?;

        // Verify old password
        if !self.password_hasher.verify_password(old_password, &user.password_hash)? {
            return Err(AuthError::InvalidCredentials);
        }

        // Hash new password
        user.password_hash = self.password_hasher.hash_password(new_password)?;
        user.updated_at = SystemTime::now();

        // Update user
        self.repository.update(&user).await?;

        Ok(())
    }

    fn validate_registration(&self, data: &RegistrationData) -> AuthResult<()> {
        // Email validation
        if !data.email.contains('@') {
            return Err(AuthError::InvalidEmail);
        }

        // Password strength validation
        if data.password.len() < 8 {
            return Err(AuthError::WeakPassword);
        }

        // Username validation
        if data.username.is_empty() || data.username.len() < 3 {
            return Err(AuthError::InvalidUsername);
        }

        Ok(())
    }
}
```

