use async_trait::async_trait;
use crate::auth::{AuthResult, User, UserId};

/// Trait for user storage operations
#[async_trait]
pub trait UserRepository: Send + Sync {
    async fn save(&self, user: &User) -> AuthResult<()>;
    async fn update(&self, user: &User) -> AuthResult<()>;
    async fn find_by_id(&self, id: UserId) -> AuthResult<Option<User>>;
    async fn find_by_email(&self, email: &str) -> AuthResult<Option<User>>;
    async fn delete(&self, id: UserId) -> AuthResult<()>;
}

/// In-memory implementation for testing
pub struct InMemoryUserRepository {
    users: std::sync::Arc<tokio::sync::RwLock<std::collections::HashMap<UserId, User>>>,
}

impl InMemoryUserRepository {
    pub fn new() -> Self {
        Self {
            users: std::sync::Arc::new(tokio::sync::RwLock::new(std::collections::HashMap::new())),
        }
    }
}

#[async_trait]
impl UserRepository for InMemoryUserRepository {
    async fn save(&self, user: &User) -> AuthResult<()> {
        let mut users = self.users.write().await;
        users.insert(user.id, user.clone());
        Ok(())
    }

    async fn update(&self, user: &User) -> AuthResult<()> {
        let mut users = self.users.write().await;
        users.insert(user.id, user.clone());
        Ok(())
    }

    async fn find_by_id(&self, id: UserId) -> AuthResult<Option<User>> {
        let users = self.users.read().await;
        Ok(users.get(&id).cloned())
    }

    async fn find_by_email(&self, email: &str) -> AuthResult<Option<User>> {
        let users = self.users.read().await;
        Ok(users.values().find(|u| u.email == email).cloned())
    }

    async fn delete(&self, id: UserId) -> AuthResult<()> {
        let mut users = self.users.write().await;
        users.remove(&id);
        Ok(())
    }
}
